{"loginUrl": "https://zoom.us/signin#/login", "userRemoveUrl": "https://us06web.zoom.us/account/user", "userRemoveGuide": "{
  "steps": [
      {
          "stepNumber": 1,
          "stepDescription": "We are on the Zoom's users page. Search user with the email: {USER_EMAIL_PLACEHOLDER} under Users tab search input. **Do not click on Advanced Search**"
      },
      {
          "stepNumber": 2,
          "stepDescription": "After you search and the user is visible, click on the Checkbox beside user. A Checked state is indicated with a tick mark in it."
      },
      {
          "stepNumber": 3,
          "stepDescription": "Click on 'Unlink' button located under users tab. **Do not click on 'Edit', 'Delete' buttons."
      },
      {
          "stepNumber": 4,
          "stepDescription": "A popup comes up, If the acknowledgement is required, then acknowledge it and Click on 'Unlink Now Without Data Transfer' to confirm And respond with DONE."
      },
      {
          "stepNumber": 5,
          "stepDescription": "If the footer of the page is visible, showing 'about', 'support' etc, then respond with DONE."
      },
      {
          "stepNumber": 6,
          "stepDescription": "If your last step was to 'Click on Unlink Now Without Data Transfer' and you have done it successfully or can't find the user, Respond with DONE."
      }
  ]
}", "customLoginPrompt": null, "userChangeRoleUrl": "https://us06web.zoom.us/account/user", "userChangeRoleGuide": "{
  "steps": [
